{
  "description": "The creature is a chimeric animal shown in left-facing profile standing on a small patch of bare earth with sparse tufts of grass. It has the overall body shape, fur, hind legs and tail of a red fox but the forelimbs are replaced by large folded bird wings and the chest, shoulders and upper back are covered in owl-like plumage. The fur is dense and reddish-orange on the head, back, sides and tail with white on the muzzle, chin, chest and belly, and the wings display buff, tan, gray and white feathers with dark speckling and barring. No other animals, objects or background elements are present.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a red fox head with a narrow pointed muzzle, black nose, amber eyes, white fur on the lower muzzle, chin and throat, and reddish-orange fur on the top of the muzzle, cheeks and forehead",
      "where": "at the top left of the body, facing left in profile"
    },
    {
      "part": "ears",
      "looks_like": "two large triangular upright pointed ears with reddish-orange outer fur, black tips and pale gray-white inner fur with dark rims",
      "where": "on top of the head, one slightly behind the other in profile"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in short reddish-brown fur that fades to tan and cream on the inner thigh and belly and darkens to brown-black near the lower leg",
      "where": "under the rear torso, bent at the hock and stifle, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "two hind paws with dark brown-black fur, rounded pads and short dark claws",
      "where": "at the bottom of the hind legs planted on the patch of ground"
    },
    {
      "part": "tail",
      "looks_like": "a single long thick bushy fox tail with long reddish-brown fur, darker guard hairs along the top and a white tip at the end",
      "where": "extending from the rump at the rear of the body to the lower right, angled downward"
    },
    {
      "part": "wings",
      "looks_like": "two large folded bird wings with layered flight feathers, the near wing more fully visible showing broad primary and secondary feathers and covert patterning",
      "where": "attached to the sides of the upper torso and shoulder area where forelimbs would be, hanging down along the sides of the body"
    },
    {
      "part": "feathers",
      "looks_like": "owl-like plumage in buff, tan, cream and gray with intricate patterning including small black spots on the chest and coverts, gray scalloped feather edges on the upper wing and shoulder, and dark horizontal bars on the flight feathers",
      "where": "covering both wings and extending onto the upper back, shoulders and sides of the chest"
    },
    {
      "part": "markings",
      "looks_like": "white underfur on the chest and belly scattered with small black dots, and the wing feathers marked with black speckles, spots and transverse bars",
      "where": "on the chest, throat and across the wing surfaces"
    }
  ],
  "attached_objects": [],
  "animals": ["fox", "owl"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
